from django.db.models import F


def marcar_modo_precio(apps, schema_editor):
    # Líneas históricas: el precio de lista era precio_venta + descuento.
    DetallePedido = apps.get_model('core', 'DetallePedido')
    DetallePedido.objects.update(precio_lista=F('precio_venta') + F('descuento_por_kilo'))
    DetallePedido.objects.filter(descuento_por_kilo__gt=0).update(modo_precio='descuento')


